// Optional server-side provider credentials. Local storage/queue/workflow bindings are generated by Wrangler.
interface Env {
  CLOUDFLARE_ACCOUNT_ID?: string;
  CLOUDFLARE_API_TOKEN?: string;
  TYPESAFE_API_KEY?: string;
  JEV_PROVIDER?: "cloudflare" | "typesafe";
  JEV_MODEL?: string;
  BROWSER_CONCURRENCY?: string;
  JEV_CONCURRENCY?: string;
  // Auth/runtime configuration, validated fail-closed by worker/config.ts.
  BETTER_AUTH_URL?: string;
  BETTER_AUTH_SECRET?: string;
  EMAIL_FROM?: string;
  AUTH_EMAIL_DAILY_LIMIT?: string;
}
